# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::ProjectionConsumer do
  it "applies a create and an update of one entry delivered in the same batch, in outbox order" do
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    create(:employment, company:, user:)
    item = lambda do |version, position|
      entry = TimekeepingSnapshots.entry(id: 90_101, company_id: company.id, version:, project_id: project.id,
                                         user_id: user.id)
      TimekeepingSnapshots.item(entry, generation: TimekeepingOwnership.current.generation, outbox_position: position)
    end

    # Listed out of order on purpose: the consumer applies snapshots in outbox_position order.
    batch = TimekeepingSnapshots.batch(item.call(2, 2), item.call(1, 1))
    result = described_class.call(batch:, idempotency_key: nil)

    # "It upserts by entry `id` and applies a snapshot only when its `version` is higher than the row's."
    expect(result.status).to eq(200)
    expect(result.body.as_json).to eq("applied" => 2, "ignored" => 0)
    row = ActiveRecord::Base.connection.select_one("SELECT version, note FROM timesheet_entries WHERE id = 90101")
    expect(row).to eq("version" => 2, "note" => "v2")
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  it "refuses a higher-version snapshot whose company_id differs from the stored row and leaves the row unchanged" do
    company_a = create(:company)
    company_b = create(:company)
    project_a = create(:project, client: create(:client, company: company_a))
    project_b = create(:project, client: create(:client, company: company_b))
    user = create(:user)
    create(:employment, company: company_a, user:)
    create(:employment, company: company_b, user:)
    batch_for = lambda do |company, project, version|
      entry = TimekeepingSnapshots.entry(id: 90_201, company_id: company.id, version:, project_id: project.id,
                                         user_id: user.id)
      TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: TimekeepingOwnership.current.generation))
    end
    read_row = -> { ActiveRecord::Base.connection.select_one("SELECT * FROM timesheet_entries WHERE id = 90201") }

    described_class.call(batch: batch_for.call(company_a, project_a, 1), idempotency_key: nil)
    before_refusal = read_row.call
    expect(before_refusal).to include("company_id" => company_a.id, "version" => 1, "note" => "v1")

    # "A snapshot whose `company_id` differs from the row's is refused."
    result = described_class.call(batch: batch_for.call(company_b, project_b, 5), idempotency_key: nil)

    expect(result.status).to eq(409)
    expect(result.body.as_json).to eq("reason" => "stale_generation")
    expect(read_row.call).to eq(before_refusal)
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  it "keeps a tombstone row and does not let a later lower version bring the entry back" do
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    create(:employment, company:, user:)
    batch_for = lambda do |version, discarded_at|
      entry = TimekeepingSnapshots.entry(id: 90_301, company_id: company.id, version:, project_id: project.id,
                                         user_id: user.id, discarded_at:)
      TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: TimekeepingOwnership.current.generation))
    end

    # "A discard arrives as a snapshot with `discarded_at` set (a 'tombstone'), never as a row delete."
    discard = described_class.call(batch: batch_for.call(3, "2026-03-03T10:00:00Z"), idempotency_key: nil)
    late = described_class.call(batch: batch_for.call(2, nil), idempotency_key: nil)

    expect(discard.body.as_json).to eq("applied" => 1, "ignored" => 0)
    expect(late.body.as_json).to eq("applied" => 0, "ignored" => 1)
    rows = ActiveRecord::Base.connection.select_all("SELECT version, discarded_at FROM timesheet_entries WHERE id = 90301").to_a
    expect(rows.size).to eq(1)
    expect(rows.first["version"]).to eq(3)
    expect(rows.first["discarded_at"]).not_to be_nil
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  it "writes projection rows with miru.writer set to projection while ordinary model saves carry no writer" do
    connection = ActiveRecord::Base.connection
    connection.execute(<<~SQL)
      CREATE TEMP TABLE projection_writer_spec_log (entry_id bigint, writer text);
      CREATE FUNCTION pg_temp.projection_writer_spec_record() RETURNS trigger AS $$
      BEGIN
        INSERT INTO projection_writer_spec_log VALUES (NEW.id, current_setting('miru.writer', true));
        RETURN NEW;
      END $$ LANGUAGE plpgsql;
      CREATE TRIGGER projection_writer_spec_trigger AFTER INSERT OR UPDATE ON timesheet_entries
        FOR EACH ROW EXECUTE FUNCTION pg_temp.projection_writer_spec_record();
    SQL
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    create(:employment, company:, user:)
    ordinary = create(:timesheet_entry, user:, project:)
    entry = TimekeepingSnapshots.entry(id: ordinary.id + 1000, company_id: company.id, version: 1,
                                       project_id: project.id, user_id: user.id)
    batch = TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: TimekeepingOwnership.current.generation))

    result = described_class.call(batch:, idempotency_key: nil)

    # "The consumer sets `SET LOCAL miru.writer = 'projection'` so a database-level guard can recognize it as
    # the projection writer."
    expect([result.status, result.body]).to eq([200, { "applied" => 1, "ignored" => 0 }])
    log = connection.select_rows("SELECT entry_id, writer FROM projection_writer_spec_log ORDER BY entry_id").to_h
    expect(log.fetch(entry["id"])).to eq("projection")
    expect(log.fetch(ordinary.id).to_s).to eq("")
  end
end
